examples.template:
ScrollView {
    VStack(alignment: .leading, spacing: theme.spacing.space4) {
        Text({{title}}).monarchTextStyle(.heading)
        Text({{description}})
        MonarchSegmentedControl(
            "Period",
            selection: $period,
            items: [
                MonarchSegmentedItem({{periods.0}}, value: {{periods.0}}),
                MonarchSegmentedItem({{periods.1}}, value: {{periods.1}}),
                MonarchSegmentedItem({{periods.2}}, value: {{periods.2}}),
                MonarchSegmentedItem({{periods.3}}, value: {{periods.3}}),
                MonarchSegmentedItem({{periods.4}}, value: {{periods.4}}),
            ],
            size: .sm
        )
        MonarchButton(isEditing ? "Done" : {{arrange}}, variant: .secondary, size: .sm) { isEditing.toggle() }
        LazyVGrid(columns: [GridItem(.adaptive(minimum: 130), spacing: theme.spacing.space3)], spacing: theme.spacing.space3) {
                MonarchStatCard({{kpis.0.label}}, value: {{kpis.0.value|double}}).id({{kpis.0.id}})
                MonarchStatCard({{kpis.1.label}}, value: {{kpis.1.value|double}}).id({{kpis.1.id}})
                MonarchStatCard(
                    {{kpis.2.label}},
                    value: {{kpis.2.value|double}},
                    change: MonarchMetricChange({{kpis.2.change.value|double}}, comparison: {{kpis.2.change.comparison}})
                )
                .id({{kpis.2.id}})
        }
        MonarchInsightStrip(
            "Insights",
            insights: [
                MonarchInsight(
                    id: {{insights.0.id}},
                    title: {{insights.0.title}},
                    why: {{insights.0.why}},
                    tone: {{insights.0.severity|tone}},
                    origin: {{insights.0.origin|case}}
                )
            ]
        )
        MonarchDashboardGrid(
            tiles,
            layout: $layout,
            itemLabel: \.title,
            span: { $0.isWide ? .two : .one },
            isEditing: isEditing,
            content: { tile in section(tile) }
        )
    }
    .padding(theme.spacing.space4)
}
.environment(\.locale, Locale(identifier: {{locale}}))
.environment(\.timeZone, TimeZone(identifier: {{timeZone}}) ?? .gmt)
.frame(maxWidth: .infinity, minHeight: theme.spacing.space24 * 6)

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var period = {{period}}
@State private var isEditing = false
@State private var layout: [String] = []
@State private var done: Set<String> = [{{today.done.0}}]

/// One widget of the home screen.
struct Tile: Identifiable {
    let id: String
    let title: String
    var isWide = false
}

private let tiles = [
    Tile(id: "today", title: {{today.title}}),
    Tile(id: "assigned", title: {{assigned.title}}),
    Tile(id: "dueSoon", title: {{dueSoon.title}}),
    Tile(id: "progress", title: {{progress.title}}),
    Tile(id: "announcements", title: {{announcements.title}}),
    Tile(id: "team", title: {{team.title}}),
    Tile(id: "activity", title: {{activity.title}}, isWide: true),
]
private let now = {{activity.now|date}}
private let tasks = [
    (id: {{today.tasks.0.id}}, title: {{today.tasks.0.title}}),
    (id: {{today.tasks.1.id}}, title: {{today.tasks.1.title}}),
    (id: {{today.tasks.2.id}}, title: {{today.tasks.2.title}}),
]

private func row(_ label: String, _ value: String) -> some View {
    HStack {
        Text(label)
        Spacer()
        Text(value)
    }
}

@ViewBuilder private func section(_ tile: Tile) -> some View {
    switch tile.id {
    case "today":
        MonarchWidget(tile.title, description: {{today.date}}) {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                Text({{today.heading}}).monarchTextStyle(.label)
                ForEach(tasks, id: \.id) { task in
                    VStack(spacing: theme.spacing.space2) {
                        HStack {
                            Text(task.title)
                                .monarchTextStyle(.body)
                                .strikethrough(done.contains(task.id))
                                .foregroundStyle(done.contains(task.id) ? theme.colors.textMuted : theme.colors.textDefault)
                            Spacer(minLength: 0)
                            if task.id == {{today.overdue.0}} { MonarchBadge("Overdue", tone: .danger) }
                        }
                        Divider()
                    }
                }
            }
        }
    case "assigned":
        MonarchWidget(tile.title) {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                HStack { Text({{assigned.rows.0.label}}); Spacer(); MonarchBadge({{assigned.rows.0.value}}, tone: {{assigned.rows.0.tone|tone}}) }
                HStack { Text({{assigned.rows.1.label}}); Spacer(); MonarchBadge({{assigned.rows.1.value}}, tone: {{assigned.rows.1.tone|tone}}) }
                HStack { Text({{assigned.rows.2.label}}); Spacer(); MonarchBadge({{assigned.rows.2.value}}, tone: {{assigned.rows.2.tone|tone}}) }
            }
        }
    case "dueSoon":
        MonarchWidget(tile.title) {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                row({{dueSoon.rows.0.label}}, {{dueSoon.rows.0.value}})
                row({{dueSoon.rows.1.label}}, {{dueSoon.rows.1.value}})
                row({{dueSoon.rows.2.label}}, {{dueSoon.rows.2.value}})
            }
        }
    case "progress":
        MonarchWidget(tile.title) {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    row({{progress.goals.0.label}}, "\({{progress.goals.0.value}})%")
                    ProgressView(value: {{progress.goals.0.value|double}}, total: 100).progressViewStyle(.monarchLinear).accessibilityLabel({{progress.goals.0.label}})
                }
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    row({{progress.goals.1.label}}, "\({{progress.goals.1.value}})%")
                    ProgressView(value: {{progress.goals.1.value|double}}, total: 100).progressViewStyle(.monarchLinear).accessibilityLabel({{progress.goals.1.label}})
                }
            }
        }
    case "announcements":
        MonarchWidget(tile.title) {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text({{announcements.items.0.term}}).monarchTextStyle(.label)
                Text({{announcements.items.0.body}})
            }
        }
    case "team":
        MonarchWidget(tile.title) {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                row({{team.rows.0.label}}, {{team.rows.0.value}})
                row({{team.rows.1.label}}, {{team.rows.1.value}})
            }
        }
    default:
        MonarchWidget(tile.title) {
            MonarchActivityTimeline(
                [
                    MonarchActivityTimelineEvent(
                        id: {{activity.events.0.id}},
                        actor: MonarchActivityTimelineActor({{activity.events.0.actor}}),
                        verb: {{activity.events.0.verb}},
                        object: {{activity.events.0.object}},
                        time: {{activity.events.0.time|date}}
                    ),
                    MonarchActivityTimelineEvent(
                        id: {{activity.events.1.id}},
                        actor: MonarchActivityTimelineActor({{activity.events.1.actor}}),
                        verb: {{activity.events.1.verb}},
                        object: {{activity.events.1.object}},
                        time: {{activity.events.1.time|date}}
                    ),
                ],
                isGroupedByDay: false,
                density: .compact,
                now: now
            )
        }
    }
}

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var period = "Last 7 days"
@State private var isEditing = false
@State private var layout: [String] = []
@State private var done: Set<String> = ["t3"]

/// One widget of the home screen.
struct Tile: Identifiable {
    let id: String
    let title: String
    var isWide = false
}

private let tiles = [
    Tile(id: "today", title: "Today"),
    Tile(id: "assigned", title: "Assigned to you"),
    Tile(id: "dueSoon", title: "Due soon"),
    Tile(id: "progress", title: "Progress"),
    Tile(id: "announcements", title: "Announcements"),
    Tile(id: "team", title: "Your team"),
    Tile(id: "activity", title: "Recent activity", isWide: true),
]
private let now = Date(timeIntervalSince1970: 1_781_517_600)
private let tasks = [
    (id: "t1", title: "Reply to the Harbor Labs request"),
    (id: "t2", title: "Review the checkout redesign"),
    (id: "t3", title: "Send the sprint notes"),
]

private func row(_ label: String, _ value: String) -> some View {
    HStack {
        Text(label)
        Spacer()
        Text(value)
    }
}

@ViewBuilder private func section(_ tile: Tile) -> some View {
    switch tile.id {
    case "today":
        MonarchWidget(tile.title, description: "Monday 15 June") {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                Text("Due today").monarchTextStyle(.label)
                ForEach(tasks, id: \.id) { task in
                    VStack(spacing: theme.spacing.space2) {
                        HStack {
                            Text(task.title)
                                .monarchTextStyle(.body)
                                .strikethrough(done.contains(task.id))
                                .foregroundStyle(done.contains(task.id) ? theme.colors.textMuted : theme.colors.textDefault)
                            Spacer(minLength: 0)
                            if task.id == "t1" { MonarchBadge("Overdue", tone: .danger) }
                        }
                        Divider()
                    }
                }
            }
        }
    case "assigned":
        MonarchWidget(tile.title) {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                HStack { Text("In progress"); Spacer(); MonarchBadge("5", tone: .info) }
                HStack { Text("In review"); Spacer(); MonarchBadge("3", tone: .warning) }
                HStack { Text("To do"); Spacer(); MonarchBadge("4", tone: .neutral) }
            }
        }
    case "dueSoon":
        MonarchWidget(tile.title) {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                row("Update the pricing page", "Wed 17 Jun")
                row("Plan the June release", "Thu 18 Jun")
                row("Write the onboarding guide", "Fri 19 Jun")
            }
        }
    case "progress":
        MonarchWidget(tile.title) {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    row("Q2 goal: ship the new checkout", "\(70)%")
                    ProgressView(value: 70.0, total: 100).progressViewStyle(.monarchLinear).accessibilityLabel("Q2 goal: ship the new checkout")
                }
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    row("Cut first reply time to one hour", "\(45)%")
                    ProgressView(value: 45.0, total: 100).progressViewStyle(.monarchLinear).accessibilityLabel("Cut first reply time to one hour")
                }
            }
        }
    case "announcements":
        MonarchWidget(tile.title) {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text("Office closed on Friday 19 June").monarchTextStyle(.label)
                Text("Everyone works from home that day.")
            }
        }
    case "team":
        MonarchWidget(tile.title) {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                row("Leave request, Jonas Weber", "22 to 26 Jun")
                row("Expense claim, Amara Okafor", "£86.40")
            }
        }
    default:
        MonarchWidget(tile.title) {
            MonarchActivityTimeline(
                [
                    MonarchActivityTimelineEvent(
                        id: "e1",
                        actor: MonarchActivityTimelineActor("Jonas Weber"),
                        verb: "commented on",
                        object: "Checkout redesign",
                        time: Date(timeIntervalSince1970: 1_781_516_400)
                    ),
                    MonarchActivityTimelineEvent(
                        id: "e2",
                        actor: MonarchActivityTimelineActor("Amara Okafor"),
                        verb: "assigned you",
                        object: "Update the pricing page",
                        time: Date(timeIntervalSince1970: 1_781_510_700)
                    ),
                ],
                isGroupedByDay: false,
                density: .compact,
                now: now
            )
        }
    }
}
